{"content":"/*
 * High-performance portfolio calculations using C extension
 *
 * Implements portfolio risk sqrt(x^T * S * x) and
 * portfolio return x^T * r using the NumPy C API.
 *
 * The risk kernel has two paths:
 *  - contiguous NumPy 2-D input: direct strided buffer loop;
 *  - Python sequence-of-sequences (e.g. list of lists): fused
 *    single-pass traversal with no temporary n x n copy, so
 *    portfolios up to 8000 assets need only O(n) extra memory.
 * Both paths accumulate in the same element order as the Python
 * baseline (row by row, j = 0..n-1, then dot with weights).
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Extract a C double from a Python scalar. Fast path for floats. */
static int
get_double(PyObject *item, double *out)
{
    if (PyFloat_CheckExact(item)) {
        *out = PyFloat_AS_DOUBLE(item);
        return 0;
    }
    double v = PyFloat_AsDouble(item);
    if (v == -1.0 && PyErr_Occurred())
        return -1;
    *out = v;
    return 0;
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *w_obj, *c_obj;

    if (!PyArg_ParseTuple(args, "OO", &w_obj, &c_obj))
        return NULL;

    /* Weights -> contiguous double buffer (1-D, small: O(n)). */
    PyArrayObject *w = (PyArrayObject *)PyArray_FROM_OTF(
        w_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (w == NULL)
        return NULL;
    if (PyArray_NDIM(w) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be 1-D");
        Py_DECREF(w);
        return NULL;
    }
    npy_intp n = PyArray_DIM(w, 0);
    double * restrict weights = (double *)PyArray_DATA(w);

    double risk_squared = 0.0;

    if (PyArray_Check(c_obj)) {
        /* Contiguous NumPy 2-D path. */
        PyArrayObject *c = (PyArrayObject *)PyArray_FROM_OTF(
            c_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (c == NULL) {
            Py_DECREF(w);
            return NULL;
        }
        if (PyArray_NDIM(c) != 2 ||
            PyArray_DIM(c, 0) != n || PyArray_DIM(c, 1) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix must be n x n where n = len(weights)");
            Py_DECREF(w);
            Py_DECREF(c);
            return NULL;
        }
        double * restrict cov = (double *)PyArray_DATA(c);
        for (npy_intp i = 0; i < n; i++) {
            double row_sum = 0.0;
            double *row = cov + i * n;
            for (npy_intp j = 0; j < n; j++) {
                row_sum += row[j] * weights[j];
            }
            risk_squared += weights[i] * row_sum;
        }
        Py_DECREF(c);
    }
    else {
        /* Sequence-of-sequences path: single fused pass, O(n) memory. */
        PyObject *fast_cov = PySequence_Fast(c_obj, "cov_matrix must be a sequence");
        if (fast_cov == NULL) {
            Py_DECREF(w);
            return NULL;
        }
        if (PySequence_Fast_GET_SIZE(fast_cov) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix must be n x n where n = len(weights)");
            Py_DECREF(fast_cov);
            Py_DECREF(w);
            return NULL;
        }
        PyObject **rows = PySequence_Fast_ITEMS(fast_cov);
        int failed = 0;
        for (npy_intp i = 0; i < n && !failed; i++) {
            PyObject *fast_row = PySequence_Fast(rows[i], "cov_matrix rows must be sequences");
            if (fast_row == NULL) {
                failed = 1;
                break;
            }
            if (PySequence_Fast_GET_SIZE(fast_row) != n) {
                PyErr_SetString(PyExc_ValueError,
                                "cov_matrix must be n x n where n = len(weights)");
                Py_DECREF(fast_row);
                failed = 1;
                break;
            }
            PyObject **items = PySequence_Fast_ITEMS(fast_row);
            double row_sum = 0.0;
            for (npy_intp j = 0; j < n; j++) {
                double s;
                if (get_double(items[j], &s) < 0) {
                    failed = 1;
                    break;
                }
                row_sum += s * weights[j];
            }
            Py_DECREF(fast_row);
            if (!failed)
                risk_squared += weights[i] * row_sum;
        }
        Py_DECREF(fast_cov);
        if (failed) {
            Py_DECREF(w);
            return NULL;
        }
    }

    Py_DECREF(w);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *w_obj, *r_obj;

    if (!PyArg_ParseTuple(args, "OO", &w_obj, &r_obj))
        return NULL;

    PyArrayObject *w = (PyArrayObject *)PyArray_FROM_OTF(
        w_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *r = (PyArrayObject *)PyArray_FROM_OTF(
        r_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (w == NULL || r == NULL) {
        Py_XDECREF(w);
        Py_XDECREF(r);
        return NULL;
    }

    if (PyArray_NDIM(w) != 1 || PyArray_NDIM(r) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights and returns must be 1-D");
        Py_DECREF(w);
        Py_DECREF(r);
        return NULL;
    }
    npy_intp n = PyArray_DIM(w, 0);
    if (PyArray_DIM(r, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and returns must have the same length");
        Py_DECREF(w);
        Py_DECREF(r);
        return NULL;
    }

    double * restrict weights = (double *)PyArray_DATA(w);
    double * restrict rets = (double *)PyArray_DATA(r);

    double total = 0.0;
    for (npy_intp i = 0; i < n; i++) {
        total += weights[i] * rets[i];
    }

    Py_DECREF(w);
    Py_DECREF(r);

    return PyFloat_FromDouble(total);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  // Initialize NumPy C API
    return PyModule_Create(&moduledef);
}
